<?php
declare( strict_types = 1 );

namespace Automattic\WooCommerce\Internal\Blocks;

use Automattic\WooCommerce\Blocks\Domain\Package;

/**
 * Registers assets and blocks generated by the block-library wp-build package.
 *
 * @since 11.0.0
 */
class BlockLibraryRegistry {

	/**
	 * Path for generated block-library build output.
	 */
	private const BUILD_PATH = 'assets/client/blocks/';

	/**
	 * Package instance.
	 *
	 * @var Package
	 */
	private Package $package;

	/**
	 * Constructor.
	 *
	 * @param Package $package Package instance.
	 */
	public function __construct( Package $package ) {
		$this->package = $package;
	}

	/**
	 * Initialize block-library asset and block registration.
	 *
	 * @internal
	 */
	final public function init(): void {
		$this->load_asset_registration();

		add_action( 'enqueue_block_editor_assets', array( $this, 'enqueue_block_editor_assets' ) );

		if ( did_action( 'init' ) ) {
			$this->register_block_types();
			return;
		}

		add_action( 'init', array( $this, 'register_block_types' ), 9 );
	}

	/**
	 * Load generated asset registration.
	 */
	public function load_asset_registration(): void {
		$build_file = $this->package->get_path( self::BUILD_PATH . 'build.php' );
		if ( ! file_exists( $build_file ) ) {
			return;
		}

		require_once $build_file;
	}

	/**
	 * Register all migrated block-library block types.
	 */
	public function register_block_types(): void {
		foreach ( $this->get_block_names() as $block_name ) {
			$this->register_block_type_from_metadata( $block_name );
		}
	}

	/**
	 * Register a block type from the block-library metadata package.
	 *
	 * @param string $block_name Block metadata directory name.
	 * @return void
	 */
	public function register_block_type_from_metadata( string $block_name ): void {
		$metadata_path = $this->get_block_metadata_path( $block_name );

		if ( ! $metadata_path ) {
			return;
		}

		$metadata = $this->get_block_metadata( $block_name );
		if (
			is_array( $metadata ) &&
			! empty( $metadata['name'] ) &&
			\WP_Block_Type_Registry::get_instance()->is_registered( $metadata['name'] )
		) {
			return;
		}

		register_block_type_from_metadata( $metadata_path );
	}

	/**
	 * Remove block types that are registered from the block-library package.
	 *
	 * @param array<int, string> $block_types Legacy block type class names.
	 * @return array<int, string>
	 */
	public function remove_migrated_block_types( array $block_types ): array {
		$migrated_block_types = array_map(
			array( $this, 'get_legacy_block_type_name' ),
			$this->get_block_names()
		);

		return array_values( array_diff( $block_types, $migrated_block_types ) );
	}

	/**
	 * Enqueue editor scripts declared by migrated block metadata.
	 */
	public function enqueue_block_editor_assets(): void {
		foreach ( $this->get_block_editor_script_handles() as $script_handle ) {
			wp_enqueue_script( $script_handle );
		}
	}

	/**
	 * Get the metadata path for a block-library block.
	 *
	 * @param string $block_name Block directory name.
	 * @return string|false Path to metadata directory, or false if not found.
	 */
	public function get_block_metadata_path( string $block_name ) {
		$metadata_path = $this->package->get_path(
			self::BUILD_PATH . $block_name . '/block.json'
		);

		if ( file_exists( $metadata_path ) ) {
			return dirname( $metadata_path );
		}

		return false;
	}

	/**
	 * Get decoded block metadata.
	 *
	 * @param string $block_name Block directory name.
	 * @return array<string, mixed>|null
	 */
	private function get_block_metadata( string $block_name ): ?array {
		$metadata_path = $this->get_block_metadata_path( $block_name );

		if ( ! $metadata_path ) {
			return null;
		}

		$metadata = wp_json_file_decode( $metadata_path . '/block.json', array( 'associative' => true ) );

		return is_array( $metadata ) ? $metadata : null;
	}

	/**
	 * Get editor script handles declared by migrated block metadata.
	 *
	 * @return array<int, string>
	 */
	private function get_block_editor_script_handles(): array {
		$script_handles = array();

		foreach ( $this->get_block_names() as $block_name ) {
			$metadata = $this->get_block_metadata( $block_name );
			if ( ! is_array( $metadata ) || empty( $metadata['editorScript'] ) ) {
				continue;
			}

			foreach ( (array) $metadata['editorScript'] as $editor_script ) {
				if ( is_string( $editor_script ) && ! str_starts_with( $editor_script, 'file:' ) ) {
					$script_handles[] = $editor_script;
				}
			}
		}

		return array_values( array_unique( $script_handles ) );
	}

	/**
	 * Convert a block directory name to its legacy block type class name.
	 *
	 * @param string $block_name Block directory name.
	 * @return string Legacy block type class name.
	 */
	private function get_legacy_block_type_name( string $block_name ): string {
		return str_replace( ' ', '', ucwords( str_replace( '-', ' ', $block_name ) ) );
	}

	/**
	 * Get block-library block directory names from generated render files.
	 *
	 * @return array<int, string>
	 */
	public function get_block_names(): array {
		$blocks_path  = $this->package->get_path( self::BUILD_PATH );
		$render_files = glob( $blocks_path . '*/index.php' );

		if ( false === $render_files ) {
			return array();
		}

		return array_values(
			array_map(
				static function ( string $render_file ): string {
					return basename( dirname( $render_file ) );
				},
				$render_files
			)
		);
	}
}
